<script setup lang="ts">
import { onMounted, ref } from "vue"; import { api } from "../lib/request";
const items=ref<any[]>([]), email=ref(""), password=ref(""), role=ref("viewer"), error=ref(""); async function load(){try{items.value=(await api<any>("/api/v1/members")).items}catch(e:any){error.value=e.message}} async function add(){try{await api("/api/v1/members",{method:"POST",body:JSON.stringify({mode:"new_user",email:email.value,initial_password:password.value,role:role.value})});email.value="";password.value="";await load()}catch(e:any){error.value=e.message}} async function remove(item:any){await api(`/api/v1/members/${item.id}`,{method:"DELETE"});await load()} onMounted(load);
</script>
<template><section><h2>成员</h2><el-alert v-if="error" :title="error" type="error"/><el-form inline @submit.prevent="add"><el-form-item label="Email"><el-input v-model="email"/></el-form-item><el-form-item label="初始密码"><el-input v-model="password" type="password"/></el-form-item><el-form-item label="角色"><el-select v-model="role"><el-option value="tenant_admin" label="Tenant admin"/><el-option value="editor" label="Editor"/><el-option value="viewer" label="Viewer"/></el-select></el-form-item><el-button type="primary" native-type="submit">创建成员</el-button></el-form><p>新用户必须在 24 小时内首次登录并修改密码。</p><el-table :data="items"><el-table-column prop="email" label="Email"/><el-table-column prop="role" label="角色"/><el-table-column prop="status" label="状态"/><el-table-column label="操作"><template #default="s"><el-button link type="danger" @click="remove(s.row)">移除</el-button></template></el-table-column></el-table></section></template>
